import logging

import torch
import triton
import triton.language as tl

from flag_gems.runtime import torch_device_fn
from flag_gems.utils import libentry

# The fallback import is relative on purpose: an absolute
# ``flag_gems.ops.bitwise_and`` import would bind to the generic pointwise
# implementation and bypass the enflame-local flat ladder (ilshift / or_tensor
# precedent).  The log prefix stays ``GEMS_ENFLAME`` because the arch package
# is imported under its short top-level name (``gcu400.ops...``), so
# tests/accuracy_utils.gems_log_prefix derives ``GEMS_ENFLAME`` here.
from .bitwise_and import bitwise_and_tensor

logger = logging.getLogger(__name__)

_INT32_MAX = torch.iinfo(torch.int32).max
_FAST_DTYPES = (torch.bool, torch.uint8, torch.int8, torch.int16, torch.int32)


@libentry()
@triton.jit(do_not_specialize=["numel"])
def and_tensor_kernel(
    x_ptr, y_ptr, out_ptr, numel, BLOCK: tl.constexpr, EXACT: tl.constexpr
):
    # Flat pid-stride walk over the whole tensor.  Every launch rides this
    # loop (grid = min(cdiv, cap)): direct one-block-per-CTA grids with small
    # tiles are catastrophic on the 11-18 stack (probe: b2048 direct 425.9us
    # vs 40.6us GSL at 2^24 int16) and grids beyond 65535 are a P19 hardware
    # abort, so the cap also keeps 1G-element shapes legal.
    pid = tl.program_id(0)
    num_pids = tl.num_programs(0)
    arange = tl.arange(0, BLOCK)
    num_blocks = (numel + BLOCK - 1) // BLOCK
    for block_id in tl.range(pid, num_blocks, num_pids, num_stages=1):
        off = block_id * BLOCK + arange
        if EXACT:
            x = tl.load(x_ptr + off)
            y = tl.load(y_ptr + off)
            tl.store(out_ptr + off, x & y)
        else:
            mask = off < numel
            x = tl.load(x_ptr + off, mask=mask, other=0)
            y = tl.load(y_ptr + off, mask=mask, other=0)
            tl.store(out_ptr + off, x & y, mask=mask)


def _flat_config(n_total, itemsize):
    # 2026-11-19 new-stack resweep (interleaved do_bench probes on GCU400/L600,
    # kernel mode w150/r60, 3 rounds, min-of-medians; see jobs/
    # j20261119123552_dfa5d700/tmp/probe1-3):
    #   * 256KB/tile is the DSM ceiling for a 2R1W stream (3 staged tensors:
    #     b262144 int16 -> OutOfResources 1835264 > 917504), and the large
    #     buckets all pin at ~3.04 TB/s with them (bool roof evidence);
    #   * num_warps=2 beats 4/8 everywhere; nw8 bool large costs +44%;
    #   * EXACT (mask-free) beats the masked arm by 0.7-1.8% at 2^30 on this
    #     stack (reverses the old-stack "masked wins large" note), num_stages=2
    #     and a 2-block unroll both lose (unroll veto re-confirmed);
    #   * grid cap 24 wins the large int16/int32 buckets (2119.1 vs 2160.5us
    #     at 2^30 int16), cap 48 for 1-byte lanes (mid bool 23.08us best).
    if n_total <= 8192:
        # Tiny shapes are event-pair floor bound (~3.2us): any block from
        # 2048 to 4096 ties; the np2 tile keeps the masked arm off exact
        # power-of-two sizes.
        return min(triton.next_power_of_2(n_total), 4096), 48
    if itemsize == 1:
        if n_total <= (1 << 24):
            return 131072, 48
        return 262144, 48
    if itemsize == 2:
        if n_total <= 65536:
            return 8192, 48
        if n_total <= (1 << 28):
            return 65536, 24
        return 131072, 24
    if n_total <= 65536:
        return 8192, 48
    if n_total <= (1 << 24):
        return 32768, 48
    return 65536, 24


def _launch(kern, grid, args, block, num_warps=2, **constexprs):
    # The external llvm converter intermittently fails on cold compiles
    # (nondeterministic host-level flake on shared nodes); retrying the
    # launch recompiles and succeeds (bitwise_and / rad2deg precedents).
    for attempt in range(3):
        try:
            with torch_device_fn.device(args[0].device):
                kern[grid](*args, num_warps=num_warps, BLOCK=block, **constexprs)
            return
        except Exception as exc:
            if attempt == 2:
                raise
            logger.warning(
                "and_tensor flat kernel launch failed (attempt %d): %s",
                attempt + 1,
                exc,
            )


def _use_fast_path(x, y):
    # Fast path covers the common case: same-shape, same-dtype, contiguous
    # device tensors with 1/2/4-byte integer or bool lanes that fit the
    # kernel's int32 indexing.  Everything else (broadcasting, mixed dtypes,
    # strided inputs, int64/uint16 lanes, huge tensors) falls back to the
    # enflame-local bitwise_and ladder / generated pointwise kernels.
    return (
        isinstance(x, torch.Tensor)
        and isinstance(y, torch.Tensor)
        and x.dtype == y.dtype
        and x.dtype in _FAST_DTYPES
        and x.is_contiguous()
        and y.is_contiguous()
        and x.shape == y.shape
        and x.device == y.device
        and x.is_cuda
        and x.numel() <= _INT32_MAX
    )


def and_tensor(self, other):
    """Bitwise AND through the tensor dunder method with tensor operands.

    ``__and__.Tensor`` and ``bitwise_and.Tensor`` are the same operation's two
    entry points in ATen (verified numerically and by schema).

    Same-shape contiguous tensor pairs take a flat 1-D grid-stride launch
    that skips the generic rank/stride analysis in ``pointwise_dynamic``.
    The 11-18 stack upgrade made one-block-per-CTA grids with small tiles
    pathologically slow (CTA issue tax) and hard-caps grid.x at 65535 (P19),
    so the walk uses ~256KB tiles under a 24/48-program grid: the large core
    shapes pin at ~3.04 TB/s (DRAM roof, 5% above torch native) and the tiny
    shapes sit on the event-pair floor.
    """
    logger.debug("GEMS_ENFLAME AND")
    if _use_fast_path(self, other):
        numel = self.numel()
        if numel == 0:
            return torch.empty_like(self)
        out = torch.empty_like(self)
        # Bool rides the int8 lane: 0/1 bytes AND identically and the i1
        # lowering is far off the byte-stream memory floor.
        if self.dtype == torch.bool:
            x_lanes = self.view(torch.int8)
            y_lanes = other.view(torch.int8)
            out_lanes = out.view(torch.int8)
        else:
            x_lanes = self
            y_lanes = other
            out_lanes = out
        block, cap = _flat_config(numel, x_lanes.element_size())
        grid = (min(triton.cdiv(numel, block), cap),)
        _launch(
            and_tensor_kernel,
            grid,
            (x_lanes, y_lanes, out_lanes, numel),
            block,
            num_warps=2,
            EXACT=numel % block == 0,
        )
        return out
    return bitwise_and_tensor(self, other)
